begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1722 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f76998ec59eb6db8507dc857' and md5(to_jsonb(t)::text)='404c98d6a01469dd00d1827c6d4b348b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f76998ec59eb6db8507dc857';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_8e93aec94e5aa892$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false},{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_8e93aec94e5aa892$::jsonb,true),'{rules,definition,description}',$text_ec7af47f958e8789$[{"id":"official-base-table","rows":[["Lanza de caballería","10 po","6 lb","1d12 perforante","+0","Gran alcance, Especial"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-reach","text":"Gran alcance. Cuando empleas un arma de este tipo, tu alcance aumenta en 1,5 m, tanto al atacar como a efectos de ataques de oportunidad.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-special","text":"Especial. Un arma con esta propiedad posee ciertas reglas inusuales que afectan a su uso, tal y como se explica en la descripción del arma (consulta “Armas especiales” en esta misma sección).","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"lance-special","text":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_ec7af47f958e8789$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_18d42b13b5ead6ca$["official-base-table","property-reach","property-special","lance-special","family-rule"]$text_18d42b13b5ead6ca$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:f76998ec59eb6db8507dc857';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f7cc21b1535dd5ae98118d7b' and md5(to_jsonb(t)::text)='ec0465d09964226d876ffa98172e036b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f7cc21b1535dd5ae98118d7b';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_ae23ed56aa8fbde8$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tus pasos no harán ruido, independientemente de la superficie que pises. También tendrás ventaja en las pruebas de Destreza (Sigilo) que requieran moverse sin hacer ruido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_ae23ed56aa8fbde8$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f7cc21b1535dd5ae98118d7b';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f88e54bf8b39875147baef8e' and md5(to_jsonb(t)::text)='44d86a34f8a3937dc8a764936df09953')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f88e54bf8b39875147baef8e';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f74e82d3c7405be2$"Objeto · Precio base · Peso\nÁbaco · 2 po · 2 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f74e82d3c7405be2$::jsonb,true),'{rules,definition,description}',$text_89f2a195eae4b3f6$[{"id":"official-table","rows":[["Ábaco","2 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_89f2a195eae4b3f6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:f88e54bf8b39875147baef8e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f9667e4c34019878374a5f6c' and md5(to_jsonb(t)::text)='184d2951cc7895f6fb91249e30d08d94')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f9667e4c34019878374a5f6c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e4aafe448d73b53f$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este prisma tiene 50 cargas. Mientras lo sostienes, puedes usar una acción para pronunciar una de las tres palabras de activación y causar uno de los siguientes efectos: • La primera palabra de activación hace que la gema emita luz brillante en un radio de 9 m y luz tenue 9 m más allá. Este efecto no gasta una carga. Dura hasta que utilices una acción adicional para repetir la palabra de activación o hasta que emplees otra función de la gema. • La segunda palabra de activación gasta 1 carga y hace que la gema dispare un rayo brillante de luz contra una criatura que puedas ver a 18 m o menos de ti. La criatura deberá superar una tirada de salvación de Constitución con CD 15 o quedará cegada durante 1 minuto. La criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. • La tercera palabra de activación gasta 5 cargas y hace que la gema refulja con una luz cegadora que se extiende en un cono de 9 m. Todas las criaturas situadas en el cono deberán realizar una tirada de salvación como si les hubiera afectado el rayo creado por la segunda palabra de activación. Cuando todas las cargas de la gema se gasten, se convertirá en una joya no mágica con un valor de 50 po.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e4aafe448d73b53f$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f9667e4c34019878374a5f6c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:f97aac9925b409067faa06fa' and md5(to_jsonb(t)::text)='35a6f63770c87a5b258e33ed0c023060')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:f97aac9925b409067faa06fa';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_1a039f41f1524ec3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta mochila posee un bolsillo central y dos laterales, cada uno de los cuales es un espacio extradimensio- nal. Cada bolsillo lateral puede contener hasta 10 kg de materia sin exceder un volumen de 0,06 m3. En el bolsillo central caben hasta 0,2 m3 o 40 kg de materia. El morral pesa siempre 2,5 kg, independientemente del contenido.\n\nMeter un objeto en su interior sigue las reglas normales de interacción con objetos. Sacar un objeto del morral cuesta una acción. Cuando metes la mano para extraer un objeto concreto, la magia hará que siempre se encuentre arriba del todo.\n\nEl morral tiene algunas limitaciones. Si se sobrecarga o si un objeto afilado lo perfora o rasga, se romperá y quedará destruido. Si se destruye, su contenido se perderá para siempre, aunque los artefactos siempre volverán a aparecer en alguna parte. Si se pone el morral del revés, su contenido se vuelca sin sufrir daño y el morral debe volver a ponerse del derecho antes de usarlo de nuevo. Si se mete dentro del morral a una criatura que necesite respirar, podrá sobrevivir durante 10 minutos; después, empezará a ahogarse.\n\nMeter el morral en el espacio extradimensional creado por una bolsa de contención, un agujero portátil o un objeto similar destruye instantánea- mente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_1a039f41f1524ec3$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:f97aac9925b409067faa06fa';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fa694e0f28f6a842eb8b74ef' and md5(to_jsonb(t)::text)='05de272b7c66715d2c2502f6d08a70bb')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fa694e0f28f6a842eb8b74ef';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_728ec3067b81e280$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 3 cargas. Mientras la empuñes, puedes usar una acción para gastar 1 de sus cargas y, si hay alguna trampa o puerta secreta situada a 9 m o menos de ti, la varita vibrará y apuntará a la más cercana. La varita recupera 1d3 cargas empleadas cada día, al amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_728ec3067b81e280$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:fa694e0f28f6a842eb8b74ef';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fa9ba84b33858e33bab59e7c' and md5(to_jsonb(t)::text)='83bcb5794e225b47b6fd86246a68a31a')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fa9ba84b33858e33bab59e7c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_ec6a0b5ccfcad873$"Objeto · Precio base · Peso\nTinta (frasco de 1 onza) · 10 po · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_ec6a0b5ccfcad873$::jsonb,true),'{rules,definition,description}',$text_28e7ba60fe4c14da$[{"id":"official-table","rows":[["Tinta (frasco de 1 onza)","10 po","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_28e7ba60fe4c14da$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:fa9ba84b33858e33bab59e7c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fc008783161bef8547e593aa' and md5(to_jsonb(t)::text)='58ed588b5e9be846ea0f728d72c3773d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fc008783161bef8547e593aa';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_a8c011a0d5114d92$"Objeto · Precio base · Peso\nJuego de dados · 1 pp · —\n\nJuegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_a8c011a0d5114d92$::jsonb,true),'{features}',$text_39ce10f378e10021$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_39ce10f378e10021$::jsonb,true),'{rules,definition,description}',$text_3ec1f6f63d132ac1$[{"id":"official-table","rows":[["Juego de dados","1 pp","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_3ec1f6f63d132ac1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:fc008783161bef8547e593aa';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fdc90a46759c54f9de9bdfd3' and md5(to_jsonb(t)::text)='eb28fd8317b9b0e200872c053c507b1a')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fdc90a46759c54f9de9bdfd3';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_585a0a0b0278bdd6$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este deslumbrante yelmo tiene incrustados 1d10 diamantes, 2d10 rubíes, 3d10 ópalos de fuego y 4d10 ópalos. Cualquier gema que se retire del yelmo se convierte en polvo. Si se retiran o se destruyen todas las gemas, el yelmo pierde su magia.\n\nMientras lo lleves puesto, obtienes lo siguientes beneficios: • Puedes usar una acción para lanzar uno de los siguientes conjuros (CD de salvación 18) usando una de las gemas del yelmo del tipo especificado como componente: bola de fuego (ópalo de fuego), luz del día (ópalo), muro de fuego (rubí) o rociada prismática (diamante). La gema se destruye cuando el conjuro se lanza, por lo que desaparecerá del yelmo. • Mientras quede al menos un diamante, el yelmo emitirá luz tenue en un radio de 9 m si hay por lo menos un muerto viviente en esa zona. Cualquier muerto viviente que comience su turno en la zona sufrirá 1d6 de daño radiante. • Mientras quede al menos un rubí en el yelmo, tendrás resistencia al daño de fuego. • Mientras quede al menos un ópalo de fuego en el yelmo, podrás utilizar una acción para pronunciar una palabra de activación y hacer que un arma que estés empuñando se envuelva en llamas. Las llamas emitirán luz brillante en un radio de 3 m y luz tenue 3 m más allá. Las llamas son inofensivas para ti y el arma. Cuando impactes con un ataque usando el arma llameante, el objetivo recibirá 1d6 de daño de fuego adicional. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o guardes el arma.\n\nTira 1d20 si llevas el yelmo puesto y sufre daño de fuego por haber fallado una tirada de salvación contra un conjuro. Si sacas un 1, las gemas restantes del yelmo emitirán rayos de luz. Salvo tú, todas las criaturas a 18 m o menos del yelmo deberán superar una tirada de salvación de Destreza con CD 17 o un rayo impactará contra ellas y sufrirán una cantidad de daño radiante igual al número de gemas del yelmo. A continuación, el yelmo y sus gemas se destruirán.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_585a0a0b0278bdd6$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:fdc90a46759c54f9de9bdfd3';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fe7e7b105892cbe04c051592' and md5(to_jsonb(t)::text)='8592c3a4621bd3b50659ca08b3a32f2c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fe7e7b105892cbe04c051592';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3977514cdc94d6b7$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta joya tiene 3 cargas. Como acción, puedes pronunciar la palabra de activación de la gema y gastar 1 carga. Durante los siguientes 10 minutos, tendrás visión verdadera hasta 36 m si miras a través de la gema.\n\nLa gema recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3977514cdc94d6b7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:fe7e7b105892cbe04c051592';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:fedd698066b62346698b608a' and md5(to_jsonb(t)::text)='852ccbfc68866bfa31ef2837c68d355f')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:fedd698066b62346698b608a';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_54a737b808cf4ff1$[{"id":"restrain-target","kind":"other","name":"Apresar con la red","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Red. Una criatura Grande o más pequeña que sea impactada por una red quedará apresada hasta ser liberada. Esta arma no tendrá efecto sobre objetivos sin forma definida o que sean de tamaño Enorme o mayor. Una criatura puede emplear su acción para hacer una prueba de Fuerza con CD 10. Si tiene éxito, podrá liberarse a sí misma o a otra criatura dentro de su alcance. Infligir 5 de daño cortante a la red (CA 10) también liberará a la criatura sin causarle daño alguno, pondrá fin al efecto y destruirá la red. Cuando utilices una acción, una acción adicional o una reacción para atacar con una red, solo podrás realizar un ataque, incluso aunque normalmente pudieras hacer más de uno.\n\nSolo un ataque por acción, acción adicional o reacción. Liberar con acción y Fuerza CD 10, o destruir la red (CA 10) con 5 de daño cortante. No se inflige ese daño a la criatura.\n\nDuración: Hasta ser liberada.\n\nAlcance: 5/15 pies.","showInActions":false}]$text_54a737b808cf4ff1$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:fedd698066b62346698b608a';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_12f1ec5a1cb0ebb47f63bf0f4f6d9732' and md5(to_jsonb(t)::text)='215095766886bf3116f5e4d7fb84d343')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_12f1ec5a1cb0ebb47f63bf0f4f6d9732';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_6fbb8ca207152d72$"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional."$text_6fbb8ca207152d72$::jsonb,true),'{features}',$text_da6d92a85c5ac3d8$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional.","showInActions":false}]$text_da6d92a85c5ac3d8$::jsonb,true),'{rules,definition,description}',$text_7ab462ea23d4b0ae$[{"id":"recovered-campaign-description","text":"Armadura de Campo Korr\nObjeto Raro\nBasada en Armadura +1\n\nHistoria\nDraven construyó esta armadura durante años.\nLa estructura incorpora:\nacero sureño;\npiezas recuperadas de ruinas;\nfragmentos de cristal luciente refinado.\nNo es tecnología aeloriana.\nPero representa el primer intento moderno de imitarla.\n\nBeneficios\nCA incluida en el cálculo.\nResistencia excepcional.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$text_7ab462ea23d4b0ae$::jsonb,true),'{catalog,revision}',$text_6b86b273ff34fce1$1$text_6b86b273ff34fce1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_acf785d664249587$["recovered-campaign-description"]$text_acf785d664249587$::jsonb?id),jsonb_build_array('recovered-campaign-description')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_12f1ec5a1cb0ebb47f63bf0f4f6d9732';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_15542c5cbb844f6c665aa92505534567' and md5(to_jsonb(t)::text)='b76475c81fc90bb6f9fed3b37bf0943b')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_15542c5cbb844f6c665aa92505534567';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_569cb37696c7d3eb$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_08ae83fa509ef72d$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_15542c5cbb844f6c665aa92505534567';
