if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_6468441ce1833cebafdd2a531d6dc09b' and md5(to_jsonb(t)::text)='e3d02b05b3d6d84b72cfba1dd3eafb6f')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_6468441ce1833cebafdd2a531d6dc09b';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{rules,definition,description}',$text_7b4b61a96e239007$[{"id":"current-description","text":"Objeto narrativo sin bonificación mecánica definida.","type":"paragraph","section":"description","sourceIds":["ece-current-copy"],"provenance":"campaign"},{"id":"recovered-campaign-description","text":"Núcleo Luciente Fragmentado\nUno de los objetos más importantes del grupo.\n\nHistoria\nAños atrás Draven participó en una excavación ilegal financiada por un noble sureño.\nAllí encontró un pequeño núcleo cristalino incrustado en una maquinaria imposible.\nEl mecanismo estaba destruido.\nEl cristal permanecía activo.\nDesde entonces lo estudia obsesivamente.\n\nLo importante\nNi Draven.\nNi Viktor.\nNi Severino.\nComprenden realmente qué es.\nPero Severino sospecha que puede constituir la clave para reproducir ciertos fenómenos observados en artefactos aelorianos.\nPor eso insiste en llevar a Draven en esta expedición.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$text_7b4b61a96e239007$::jsonb,true),'{catalog,revision}',$text_6b86b273ff34fce1$1$text_6b86b273ff34fce1$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_d18eb8837908ca8b$["current-description","recovered-campaign-description"]$text_d18eb8837908ca8b$::jsonb?id),jsonb_build_array('current-description')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_6468441ce1833cebafdd2a531d6dc09b';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_68fb88a0772f4ac195a46f37fb7f9c32' and md5(to_jsonb(t)::text)='cf51396a16e0d075e670cd578a1abef4')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_68fb88a0772f4ac195a46f37fb7f9c32';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5615c435e74bef0a$::jsonb,true),'{features}',$text_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_6268396968fa5288$::jsonb,true),'{rules,definition,description}',$text_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_f8f536bb79fb87b3$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_68fb88a0772f4ac195a46f37fb7f9c32';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_6a6ac05b61e07639932c9c40b37b1521' and md5(to_jsonb(t)::text)='ec8d6321b10f01f9fb4f96c976e9a665')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_6a6ac05b61e07639932c9c40b37b1521';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_1c6fcc112db180f2$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Bolsa de contención creada mediante Replicar objeto mágico.\n\nEsta bolsa posee un espacio interior considerablemente mayor que sus dimensiones exteriores, que son de 60 cm de diámetro en la abertura y 1,2 m de profundidad. La bolsa puede contener hasta 250 kg, con un volumen máximo de 2 m3. La bolsa pesa 7,5 kg, independientemente de su contenido. Sacar un objeto de la bolsa cuesta una acción.\n\nSi se sobrecarga, perfora o rasga la bolsa, esta se rompe y se destruye, y su contenido se dispersa por el Plano Astral. Si se pone la bolsa del revés, su contenido se vuelca sin sufrir daño, pero la bolsa debe volver a ponerse del derecho antes de usarla de nuevo. Las criaturas que se encuentren en el interior de la bolsa y que necesiten respirar podrán sobrevivir una cantidad de minutos igual a 10 dividida entre el número de criaturas (como mínimo 1 minuto). Después, se ahogarán.\n\nMeter una bolsa de contención en el espacio extradimensional creado por un morral práctico, un agujero portátil o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.","showInActions":false}]$text_1c6fcc112db180f2$::jsonb,true),'{catalog,revision}',$text_6b86b273ff34fce1$1$text_6b86b273ff34fce1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_6a6ac05b61e07639932c9c40b37b1521';
