if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_7864d6cfd26ff2a3ec8c166d0281e3d3' and md5(to_jsonb(t)::text)='ee52fd2f87db3c85ac3eda1f65a9d622')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_7864d6cfd26ff2a3ec8c166d0281e3d3';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1100fe11a92e9703$"Objeto · Precio base · Peso\nHerramientas de manitas · 50 po · 10 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1100fe11a92e9703$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_0e984290eec89789$[{"id":"official-table","rows":[["Herramientas de manitas","50 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_0e984290eec89789$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),tru