if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_aee96a5a7c9f10db7e215b35eee2ee93' and md5(to_jsonb(t)::text)='370a24eff9daedc4317dc4c01ff12abf')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_aee96a5a7c9f10db7e215b35eee2ee93';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f6dd41d6d6cb54a8$"Objeto · Precio base · Peso\nHerramientas de herrero · 20 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f6dd41d6d6cb54a8$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_fffb5f0692bd7e5b$[{"id":"official-table","rows":[["Herramientas de herrero","20 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_fffb5f0692bd7e5b$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_aee96a5a7c9f10db7e215b35eee2ee93';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_cd497ad537a743bdc064ad8ba403b642' and md5(to_jsonb(t)::text)='5605b6bc9763c2072078f278d569a46e')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_cd497ad537a743bdc064ad8ba403b642';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_b83c61166f4697f2$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Monóculo Analítico\nObjeto Poco Común\nBasado en Gafas de Identificación.\n\nHistoria\nPermite analizar:\ninscripciones;\nmecanismos;\nestructuras mágicas.\nFue entregado personalmente por Viktor.","showInActions":false}]$text_b83c61166f4697f2$::jsonb,true),'{catalog,revision}',$text_6b86b273ff34fce1$1$text_6b86b273ff34fce1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_cd497ad537a743bdc064ad8ba403b642';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_ff87d0edefc9ba6089c0f996c535946d' and md5(to_jsonb(t)::text)='7d99dd7a3549a65d5abadb6af340c8f0')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_ff87d0edefc9ba6089c0f996c535946d';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_29de674beabfb97f$"Objeto · Precio base · Peso\nFuego de alquimista (frasco) · 50 po · 1 lb\n\nFuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_29de674beabfb97f$::jsonb,true),'{features}',$text_e827c91874ef8602$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_e827c91874ef8602$::jsonb,true),'{rules,definition,description}',$text_fc80bfec3e404bfa$[{"id":"official-table","rows":[["Fuego de alquimista (frasco)","50 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Fuego de alquimista. Este fluido pegajoso y adherente prende al entrar en contacto con el aire. Como acción, puedes lanzar este frasco hasta a 6 m, lo que hará que se rompa con el impacto. Haz un ataque a distancia contra una criatura u objeto y trata el fuego de alquimista como un arma improvisada. Si impacta, el objetivo sufre 1d4 de daño de fuego al principio de cada uno de sus turnos. Una criatura puede poner fin a este efecto si usa su acción para realizar una prueba de Destreza con CD 10 para extinguir las llamas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_fc80bfec3e404bfa$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_116845116f22e81490bfe826e33bd37a' and entity_id='inv_ff87d0edefc9ba6089c0f996c535946d';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_1611bca69dcab876392c1a1d4e6e809b' and md5(to_jsonb(t)::text)='2fdccb1435b062b8f5b320cc9bf17643')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_1611bca69dcab876392c1a1d4e6e809b';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5a9e9ab74e4d27e0$"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador."$text_5a9e9ab74e4d27e0$::jsonb,true),'{features}',$text_f6ab809ed8a351e6$[{"id":"agati-ac","kind":"passive","name":"Protección de Agati","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_f6ab809ed8a351e6$::jsonb,true),'{rules,definition,description}',$text_6bc6c02f7614387b$[{"id":"campaign-text-0","text":"Esta túnica ligera está confeccionada con telas finas y flexibles, atravesadas por delicadas runas protectoras bordadas con hilo arcano casi imperceptible. Su diseño se atribuye al sabio Agati, quien sostenía que la defensa más perfecta no debía entorpecer ni el cuerpo ni la mente.\n\nMientras lleves puesta la túnica, tu Clase de Armadura aumenta en +3, envolviéndote en un campo protector sutil que desvía golpes y atenúa impactos sin recurrir a peso ni rigidez.\n\nLa túnica no se considera armadura y puede usarse sin interferir con el lanzamiento de conjuros, permitiendo que la energía mágica fluya con total libertad a través del portador.","type":"paragraph","section":"rules","sourceIds":["ece-authored-rule"],"provenance":"campaign"}]$text_6bc6c02f7614387b$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_fc5f9352c74f6058$["campaign-text-0"]$text_fc5f9352c74f6058$::jsonb?id),jsonb_build_array('campaign-text-0')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_1611bca69dcab876392c1a1d4e6e809b';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_1c683d5ca5fbabcaa7be26e65434a3b9' and md5(to_jsonb(t)::text)='5a0f041eb4281fc6ab9d02df3f3f8e68')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_1c683d5ca5fbabcaa7be26e65434a3b9';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f74e82d3c7405be2$"Objeto · Precio base · Peso\nÁbaco · 2 po · 2 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f74e82d3c7405be2$::jsonb,true),'{rules,definition,description}',$text_89f2a195eae4b3f6$[{"id":"official-table","rows":[["Ábaco","2 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_89f2a195eae4b3f6$::jsonb,true),'{catalog,revision}',$text_4e07408562bedb8b$3$text_4e07408562bedb8b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_1c683d5ca5fbabcaa7be26e65434a3b9';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_287ad8a6f407e5a55c1a734ca4ae1247' and md5(to_jsonb(t)::text)='a97e7257cf3e4d4f565b29cd05834c9d')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_287ad8a6f407e5a55c1a734ca4ae1247';end if;update public.campaign_state_fragments set payload=jsonb_set(payload,'{features}',$text_f9ca57475e8fe81d$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Saquito de componentes. Una pequeña bolsa hermética de cuero para el cinturón con bolsillos que contienen todos los componentes materiales y otros objetos especiales necesarios para lanzar conjuros. No incluye los componentes que tengan un coste específico (estos se indican en la descripción de cada conjuro).\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$text_f9ca57475e8fe81d$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_287ad8a6f407e5a55c1a734ca4ae1247';
if not exists(select 1 from public.campaign_state_fragments t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_3af20f083b688edfa98e2b6ab330e558' and md5(to_jsonb(t)::text)='10584593d7e0a58f70dff142dee3b552')then raise exception 'ITEM_TEXT_CONFLICT:inventory:inv_3af20f083b688edfa98e2b6ab330e558';end if;update public.campaign_state_fragments set payload=jsonb_set(jsonb_set(payload,'{features}',$text_4075f39b58eb84a0$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puestas estas botas, tendrás una velocidad volando igual a tu velocidad caminando. Puedes utilizar las botas para volar durante 4 horas como máximo, ya sea de una vez o en varios vuelos más cortos, que emplearán como mínimo 1 minuto de la duración. Si estás volando cuando concluya la duración, descenderás a una velocidad de 9 m por asalto hasta que aterrices.\n\nLas botas recuperan 2 horas de vuelo por cada 12 horas que no se utilicen.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4075f39b58eb84a0$::jsonb,true),'{catalog,revision}',$text_4b227777d4dd1fc6$4$text_4b227777d4dd1fc6$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_25160f73dc28f54f059e626dcb2ef288' and entity_id='inv_3af20f083b688edfa98e2b6ab330e558';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';update public.campaign_character_versions set revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and character_id in('chr_116845116f22e81490bfe826e33bd37a','chr_25160f73dc28f54f059e626dcb2ef288');end $text$;select 18 as batch,36 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;